mapper.select:
SELECT tp.id_product AS idProduct, tp.name AS name, tp.description AS description, tp.sku_code AS skuCode, tp.min_stock_alert AS minStockAlert, tp.category_id AS categoryId, tc.name AS categoryName, tp.active AS active FROM stock_schema.tb_product tp INNER JOIN stock_schema.tb_category tc ON tc.id_category = tp.category_id
AND tp.name LIKE CONCAT('%', #{name}, '%')
AND tp.sku_code = #{skuCode}
AND tp.category_id = #{categoryId}
AND tp.active = #{active}
